from collections import deque
class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        pts = [(kx, ky)] + [(x, y) for x, y in positions]
        m = n + 1
        D = [[0] * m for _ in range(m)]
        MV = ((1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2))
        for s0 in range(m):
            sx, sy = pts[s0]
            d = [[-1] * 50 for _ in range(50)]
            d[sx][sy] = 0
            q = deque([(sx, sy)])
            while q:
                x, y = q.popleft()
                for dx, dy in MV:
                    a, b = x + dx, y + dy
                    if 0 <= a < 50 and 0 <= b < 50 and d[a][b] < 0:
                        d[a][b] = d[x][y] + 1
                        q.append((a, b))
            for t0 in range(m):
                D[s0][t0] = d[pts[t0][0]][pts[t0][1]]
        INF = float('inf')
        full = 1 << n
        dp = [[INF] * n for _ in range(full)]
        for i in range(n):
            dp[1 << i][i] = D[0][i + 1]
        for mask in range(full):
            alice = bin(mask).count('1') % 2 == 0
            for i in range(n):
                cur = dp[mask][i]
                if cur == INF or not (mask >> i) & 1:
                    continue
                for k in range(n):
                    if (mask >> k) & 1:
                        continue
                    v = cur + D[i + 1][k + 1]
                    nm = mask | (1 << k)
                    if alice:
                        if dp[nm][k] == INF or v > dp[nm][k]:
                            dp[nm][k] = v
                    else:
                        if v < dp[nm][k]:
                            dp[nm][k] = v
        return max(dp[full - 1])

