class Solution {
public:
    int maxMoves(int kx, int ky, vector<vector<int>>& positions) {
        int n = positions.size(), m = n + 1;
        vector<array<int,2>> pts(m);
        pts[0] = {kx, ky};
        for (int i = 0; i < n; i++) pts[i+1] = {positions[i][0], positions[i][1]};
        int dx[8] = {1,2,2,1,-1,-2,-2,-1}, dy[8] = {2,1,-1,-2,-2,-1,1,2};
        vector<vector<int>> D(m, vector<int>(m));
        for (int s = 0; s < m; s++) {
            int d[50][50]; memset(d, -1, sizeof d);
            queue<pair<int,int>> q;
            d[pts[s][0]][pts[s][1]] = 0; q.push({pts[s][0], pts[s][1]});
            while (!q.empty()) {
                auto [x, y] = q.front(); q.pop();
                for (int t = 0; t < 8; t++) {
                    int a = x + dx[t], b = y + dy[t];
                    if (a >= 0 && a < 50 && b >= 0 && b < 50 && d[a][b] < 0) {
                        d[a][b] = d[x][y] + 1; q.push({a, b});
                    }
                }
            }
            for (int t = 0; t < m; t++) D[s][t] = d[pts[t][0]][pts[t][1]];
        }
        const long long INF = 1e18;
        int full = 1 << n;
        vector<vector<long long>> dp(full, vector<long long>(n, INF));
        for (int i = 0; i < n; i++) dp[1 << i][i] = D[0][i+1];
        for (int mask = 0; mask < full; mask++) {
            bool alice = __builtin_popcount(mask) % 2 == 0;
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == INF || !((mask >> i) & 1)) continue;
                for (int k = 0; k < n; k++) {
                    if ((mask >> k) & 1) continue;
                    long long v = dp[mask][i] + D[i+1][k+1];
                    auto& r = dp[mask | (1 << k)][k];
                    if (alice) { if (r == INF || v > r) r = v; }
                    else if (v < r) r = v;
                }
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = max(ans, dp[full-1][i]);
        return (int)ans;
    }
};

