class Solution {
    public int maxMoves(int kx, int ky, int[][] positions) {
        int n = positions.length, m = n + 1;
        int[][] pts = new int[m][2];
        pts[0] = new int[]{kx, ky};
        for (int i = 0; i < n; i++) { pts[i+1][0] = positions[i][0]; pts[i+1][1] = positions[i][1]; }
        int[] dx = {1,2,2,1,-1,-2,-2,-1}, dy = {2,1,-1,-2,-2,-1,1,2};
        int[][] D = new int[m][m];
        for (int s = 0; s < m; s++) {
            int[][] d = new int[50][50];
            for (int[] r : d) java.util.Arrays.fill(r, -1);
            java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
            d[pts[s][0]][pts[s][1]] = 0; q.add(new int[]{pts[s][0], pts[s][1]});
            while (!q.isEmpty()) {
                int[] c = q.poll(); int x = c[0], y = c[1];
                for (int t = 0; t < 8; t++) {
                    int a = x + dx[t], b = y + dy[t];
                    if (a >= 0 && a < 50 && b >= 0 && b < 50 && d[a][b] < 0) {
                        d[a][b] = d[x][y] + 1; q.add(new int[]{a, b});
                    }
                }
            }
            for (int t = 0; t < m; t++) D[s][t] = d[pts[t][0]][pts[t][1]];
        }
        long INF = Long.MAX_VALUE / 4;
        int full = 1 << n;
        long[][] dp = new long[full][n];
        for (long[] r : dp) java.util.Arrays.fill(r, INF);
        for (int i = 0; i < n; i++) dp[1 << i][i] = D[0][i+1];
        for (int mask = 0; mask < full; mask++) {
            boolean alice = Integer.bitCount(mask) % 2 == 0;
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == INF || (mask >> i & 1) == 0) continue;
                for (int k = 0; k < n; k++) {
                    if ((mask >> k & 1) != 0) continue;
                    long v = dp[mask][i] + D[i+1][k+1];
                    if (alice) { if (dp[mask | 1 << k][k] == INF || v > dp[mask | 1 << k][k]) dp[mask | 1 << k][k] = v; }
                    else if (v < dp[mask | 1 << k][k]) dp[mask | 1 << k][k] = v;
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) ans = Math.max(ans, dp[full-1][i]);
        return (int) ans;
    }
}

