var maxMoves = function(kx, ky, positions) {
  const n = positions.length, m = n + 1;
  const pts = [[kx, ky], ...positions];
  const DX = [1,2,2,1,-1,-2,-2,-1], DY = [2,1,-1,-2,-2,-1,1,2];
  const D = Array.from({length: m}, () => new Array(m).fill(0));
  for (let s = 0; s < m; s++) {
    const d = Array.from({length: 50}, () => new Array(50).fill(-1));
    d[pts[s][0]][pts[s][1]] = 0;
    const q = [[pts[s][0], pts[s][1]]];
    while (q.length) {
      const [x, y] = q.shift();
      for (let t = 0; t < 8; t++) {
        const a = x + DX[t], b = y + DY[t];
        if (a >= 0 && a < 50 && b >= 0 && b < 50 && d[a][b] < 0) {
          d[a][b] = d[x][y] + 1; q.push([a, b]);
        }
      }
    }
    for (let t = 0; t < m; t++) D[s][t] = d[pts[t][0]][pts[t][1]];
  }
  const bc = x => { let c = 0; while (x) { x &= x - 1; c++; } return c; };
  const INF = Infinity, full = 1 << n;
  const dp = Array.from({length: full}, () => new Array(n).fill(INF));
  for (let i = 0; i < n; i++) dp[1 << i][i] = D[0][i + 1];
  for (let mask = 0; mask < full; mask++) {
    const alice = bc(mask) % 2 === 0;
    for (let i = 0; i < n; i++) {
      if (dp[mask][i] === INF || !(mask >> i & 1)) continue;
      for (let k = 0; k < n; k++) {
        if (mask >> k & 1) continue;
        const v = dp[mask][i] + D[i + 1][k + 1];
        const nm = mask | (1 << k);
        if (alice) { if (dp[nm][k] === INF || v > dp[nm][k]) dp[nm][k] = v; }
        else if (v < dp[nm][k]) dp[nm][k] = v;
      }
    }
  }
  return Math.max(...dp[full - 1]);
};
